import triton
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@triton.constexpr_function
def _tile_config(one_tile):
    if one_tile:
        return (256, 8, 512, 0)
    return (128, 4, 128, 2)

@triton.constexpr_function
def _latent_layout(quantize, operand, block, dtype):
    if not quantize:
        return gl.SwizzledSharedLayout(16, 1, 16, [1, 0])
    layout = gl.amd.cdna4.compute_efficient_padded_shared_layout(operand, [512, block], dtype, True)
    return gl.PaddedSharedLayout(layout.interval_padding_pairs, [[b[1], b[0]] for b in layout.offset_bases], [[b[1], b[0]] for b in layout.cga_layout], [layout.shape[1], layout.shape[0]])

@gluon.jit
def _gather_cache(KV, slot, channel, valid, BUFFER: gl.constexpr, FULL: gl.constexpr):
    if FULL:
        address = slot
    else:
        address = gl.maximum(slot, 0)
    if BUFFER:
        offset = address.to(gl.uint32) * 576 + channel.to(gl.uint32)
        if FULL:
            return gl.amd.cdna4.buffer_load(KV, offset)
        return gl.amd.cdna4.buffer_load(KV, offset, valid, 0.0)
    pointer = KV + address.to(gl.int64) * 576 + channel
    if FULL:
        return gl.load(pointer)
    return gl.load(pointer, valid, 0.0)

@gluon.jit
def _direct_rope(KV, Slots, row, start, TOPK: gl.constexpr, B: gl.constexpr, LAYOUT: gl.constexpr, BUFFER: gl.constexpr, FULL: gl.constexpr):
    i = start + gl.arange(0, B, layout=gl.SliceLayout(0, LAYOUT))
    d = 512 + gl.arange(0, 64, layout=gl.SliceLayout(1, LAYOUT))
    if FULL:
        slot = gl.load(Slots + row * TOPK + i)
        valid = gl.full((B,), True, gl.int1, gl.SliceLayout(0, LAYOUT))
    else:
        slot = gl.load(Slots + row * TOPK + i, i < TOPK, -1)
        valid = (i < TOPK) & (slot >= 0)
    return _gather_cache(KV, slot[None, :], d[:, None], valid[None, :], BUFFER, FULL)

@gluon.jit
def _stable_softmax(score, maximum, denominator, valid, FULL: gl.constexpr):
    next_max = gl.maximum(maximum, gl.max(score, 1))
    safe_max = gl.where(next_max == -float('inf'), 0, next_max)
    alpha = gl.exp(maximum - safe_max)
    probability = gl.exp(score - safe_max[:, None])
    if not FULL:
        probability = gl.where(valid, probability, 0)
    denominator = denominator * alpha + gl.sum(probability, 1)
    return (probability, next_max, denominator, alpha)

@gluon.jit
def _guarded_softmax(score, maximum, denominator, valid, FULL: gl.constexpr):
    base = gl.where(maximum == -float('inf'), 0, maximum)
    trial = gl.exp(score - base[:, None])
    trial_sum = gl.sum(trial, 1)
    bad = (trial_sum < 1) | (trial_sum > 32768) | (trial_sum != trial_sum)
    if gl.max(bad.to(gl.int32), 0) == 0:
        alpha = gl.full(maximum.shape, 1, gl.float32, maximum.type.layout)
        probability = trial
        next_max = base
        denominator = denominator + trial_sum
    else:
        probability, next_max, denominator, alpha = _stable_softmax(score, maximum, denominator, valid, FULL)
    return (probability, next_max, denominator, alpha)
